#include<bits/stdc++.h>
using namespace std;
const int N = 1e5+10;
vector<int> g[N];
int col[N],num[N];
int ans,sum;
void calc(int x,int fa){
    num[x]+=col[x];
    for(auto i:g[x]){
        if(i!=fa){
            calc(i,x);
            num[x]+=num[i];
        }
    }
}
void dfs(int x,int fa){
    int fl=0;
    if(num[x]!=sum&&num[x]!=0)fl=1;
    for(auto i:g[x]){
        if(i!=fa){
            dfs(i,x);
            if(num[i]!=0&&num[i]!=num[x]-col[x]){
                fl=1;
            }
        }
    }
    if(fl==1&&col[x]!=1)ans++;
}
int main(){
    int n;
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>col[i];
        sum+=col[i];
    }
    for(int i=1;i<n;i++){
        int u,v;
        cin>>u>>v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    calc(1,0);
    dfs(1,0);
    cout<<ans<<"\n";
}

#include<bits/stdc++.h>
using namespace std;
map<int,int> mp;
const int N = 1e5+10;
int calc(int x) {
    int res = 0;
    for (int i = 2; i * i <= x; i++) {
        if (x % i == 0) {
            while (x% i == 0){
                x/= i;
                res^=(1<<(i-1));
            }
        }
    }
    if (x != 1) {
        res^=(1<<(x-1));
    }
    return res;
}
int a[N];
int main(){
    int n;
    cin>>n;
    long long ans = 0;
    int pre = 0;
    for(int i=1;i<=n;i++){
        cin>>a[i];
        int res = calc(a[i]);
        pre^=res;
        if(pre==0)
            ans++;
        ans+=mp[pre];
        mp[pre]+=1;

    }
    cout<<ans<<"\n";
}
